export function parseCSV(text){
 const rows=[];let row=[],field='',quoted=false;
 for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(field);field='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(Boolean))rows.push(row);row=[];field='';}else field+=c;}
 if(field||row.length){row.push(field);rows.push(row);}const head=rows.shift().map(x=>x.replace(/^\uFEFF/,''));return rows.map(r=>Object.fromEntries(head.map((k,i)=>[k,r[i]??''])));
}
export const TODAY='2026-07-15';
export function validateProfile(p){const errors=[];if(!['prof','micro','multi','mfg'].includes(p.segment))errors.push('Choose a business type.');for(const k of ['employees','sites','budget'])if(!Number.isInteger(+p[k])||+p[k]<1||+p[k]>(k==='budget'?1000000:1000))errors.push(`Enter a valid ${k}.`);if(![1,2].includes(+p.tier))errors.push('Only tier 1 and 2 are in this catalogue.');return errors;}
export function gstValid(id){id=String(id).trim().toUpperCase();if(!/^\d{2}[A-Z]{5}\d{4}[A-Z][1-9A-Z]Z[0-9A-Z]$/.test(id))return false;const chars='0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';let factor=2,sum=0;for(let i=13;i>=0;i--){const a=chars.indexOf(id[i])*factor;sum+=Math.floor(a/36)+a%36;factor=factor===2?1:2;}return chars[(36-sum%36)%36]===id[14];}
export const mask=id=>id?String(id).slice(0,2)+'••••••••'+String(id).slice(-4):'Not supplied';
export const normalize=s=>String(s??'').toLowerCase().replace(/[^a-z0-9]/g,'');
export function eligible(product,p,{gstStatus=null,strict=false}={}){const e=[];if(!product.available_city_tiers.split(';').includes(String(p.tier)))e.push('Unavailable in this city tier');if(+p.employees<+product.min_employees)e.push(`Needs at least ${product.min_employees} employees`);if(+p.sites<+product.min_sites)e.push(`Needs at least ${product.min_sites} sites`);if(product.requires_gstin==='Y'&&(!p.hasGst||(strict&&gstStatus!=='Active')))e.push('Requires a valid, active GSTIN');return e;}
export function quote(catalogue,bundle,p,options={}){const errors=validateProfile(p);const lines=[];const ids=Object.keys(bundle).filter(id=>bundle[id]>0);if(!ids.length)errors.push('Choose at least one product.');for(const [id,qty] of Object.entries(bundle)){if(qty===0)continue;const product=catalogue.find(x=>x.product_id===id);if(!product){errors.push('Unknown product '+id);continue;}if(!Number.isInteger(qty)||qty<1||qty>1000){errors.push(id+': quantity must be 1–1000');continue;}errors.push(...eligible(product,p,options).map(e=>id+': '+e));if(product.requires_one_of&&!product.requires_one_of.split('|').some(dep=>ids.includes(dep)))errors.push(id+': needs '+product.requires_one_of.split('|').join(' or '));lines.push({...product,qty,monthly:+product.price_min_inr_per_month*qty,setup:+product.one_time_setup_inr*qty});}
 const subtotal=lines.reduce((s,l)=>s+l.monthly,0),setup=lines.reduce((s,l)=>s+l.setup,0),tax=Math.round(subtotal*.18*100)/100,setupTax=Math.round(setup*.18*100)/100;
 return{lines,errors,subtotal,setup,tax,setupTax,total:subtotal+tax,firstPayment:subtotal+tax+setup+setupTax,contract:Math.max(0,...lines.map(l=>+l.min_contract_months)),installDays:Math.max(0,...lines.map(l=>+l.typical_install_days)),overBudget:subtotal>+p.budget};
}
export function recommend(catalogue,p){if(validateProfile(p).length)throw new Error('Invalid profile');const n=Math.min(+p.employees,1000),s=Math.min(+p.sites,1000);let b={};if(p.segment==='micro')b={P01:s,P07:1,P18:1};else if(p.segment==='multi')b={P02:s,P09:s,...(+p.employees>=10&&+p.sites>=3&&p.hasGst?{P10:s}:{})};else if(p.segment==='mfg')b=p.hasGst&&+p.employees>=10?{P05:s,P21:s}:{P02:s,P20:n};else b={P02:s,P09:s,P16:n,P20:n};
 if(p.priority==='lowest_cost'||quote(catalogue,b,p).overBudget){delete b.P10;delete b.P21;delete b.P09;if(b.P02){b.P01=b.P02;delete b.P02;}}
 return {bundle:b,quote:quote(catalogue,b,p),reason:p.language==='hi'?'आपकी टीम और बजट के आधार पर यह पैकेज चुना गया है। कीमतें कैटलॉग से तय होती हैं।':'This bundle matches your team size and location. Connectivity supports daily work; optional tools can be removed before checkout.'};
}
export function removeWithDependants(catalogue,bundle,id){const next={...bundle};delete next[id];let changed=true;while(changed){changed=false;for(const key of Object.keys(next)){const p=catalogue.find(p=>p.product_id===key);if(p?.requires_one_of&&!p.requires_one_of.split('|').some(x=>next[x]>0)){delete next[key];changed=true;}}}return next;}
export function extractFields(text,kind){const clean=text.replace(/\r/g,'');const lines=clean.split('\n').map(x=>x.trim()).filter(Boolean);const find=(label)=>{const idx=lines.findIndex(l=>label.test(l));if(idx<0)return '';return lines[idx].replace(label,'').trim()||lines[idx+1]||'';};const date=/\d{4}-\d{2}-\d{2}/;
 const addressBetween=(start,end)=>{const a=clean.match(new RegExp(start+'([\\s\\S]*?)'+end,'i'));return a?a[1].replace(/place of business/ig,'').replace(/\\s+/g,' ').trim():'';}; const base={text,confidence:0};if(kind==='gst')return{...base,gstin:clean.match(/\b\d{2}[A-Z]{5}\d{4}[A-Z][1-9A-Z]Z[0-9A-Z]\b/)?.[0]||'',business:find(/^Trade name\s*/i),legal:find(/^Legal name\s*/i),address:addressBetween('Address of principal','Date of liability')};
 if(kind==='udyam')return{...base,udyam:clean.match(/UDYAM-[A-Z]{2}-\d{2}-\d{7}/)?.[0]||'',business:find(/^(?:Name of enterprise|Enterprise name)\s*/i)};
 if(kind==='address')return{...base,business:find(/^Billed to\s*/i),date:find(/^Bill date\s*/i).match(date)?.[0]||'',postcode:clean.match(/\b\d{6}\b/)?.[0]||'',address:addressBetween('Supply address','Bill date')};
 return{...base,signatory:find(/^Name\s*/i),business:find(/^For business\s*/i),expiry:find(/^Valid till\s*/i).match(date)?.[0]||''};
}
export function checkKYC({consent,confirmed,hasGst,gstin,udyam,docs},gstRows,udyamRows){
 const issues=[];if(!consent)return{status:'consent_required',issues:['Consent is required before processing.']};
 const record=gstRows.find(r=>r.gstin===String(gstin).trim().toUpperCase());const u=udyamRows.find(r=>r.udyam_number===String(udyam).trim().toUpperCase());
 if(!confirmed)issues.push('Confirm all extracted fields before validation.');if(hasGst){if(!gstValid(gstin))issues.push('GSTIN format/checksum failed.');if(!record)issues.push('GSTIN was not found in the mock registry.');else if(record.status!=='Active')issues.push('GST status is '+record.status+'. Manual review required.');if(!docs.gst)issues.push('Upload the GST certificate.');else if(docs.gst.gstin!==gstin)issues.push('Certificate GSTIN does not match the declared GSTIN.');}
 if(docs.udyam&&!docs.udyam.udyam)issues.push('Udyam certificate number is unreadable.');if(udyam&&!u)issues.push('Udyam number was not found in the mock registry.');if(udyam&&!docs.udyam)issues.push('Upload the Udyam certificate.');if(docs.udyam&&udyam!==docs.udyam.udyam)issues.push('Udyam certificate number does not match.');
 for(const kind of ['address','id'])if(!docs[kind])issues.push('Upload '+(kind==='id'?'signatory ID.':'address proof.'));
 const business=record?.trade_name||u?.enterprise_name;
 if(!business)issues.push('A reviewer must verify the alternative business registration.');
 for(const [kind,d]of Object.entries(docs)){if(d.confidence<65)issues.push(kind+': OCR confidence is low. Ask a reviewer to inspect the original.');if(!d.business)issues.push(kind+': business name is missing.');else if(business&&normalize(d.business)!==normalize(business))issues.push(kind+': business name differs from the registry.');}
 if(record&&docs.gst&&!docs.gst.legal)issues.push('GST legal name is missing.');if(record&&docs.gst?.address&&normalize(docs.gst.address)!==normalize(record.principal_place_of_business))issues.push('GST certificate address differs from the registry.');if(record&&docs.gst?.legal&&normalize(docs.gst.legal)!==normalize(record.legal_name))issues.push('GST legal name differs from the registry.');
 if(u&&record&&normalize(u.enterprise_name)!==normalize(record.trade_name))issues.push('GST and Udyam business names differ.');
 if(docs.address){const dt=Date.parse(docs.address.date),age=(Date.parse(TODAY)-dt)/86400000;if(!Number.isFinite(age)||age<0||age>90)issues.push('Address proof must be dated within 90 days of '+TODAY+'.');if(record&&normalize(docs.address.address)!==normalize(record.principal_place_of_business))issues.push('Full address differs from the GST registry.');const expected=record?.principal_place_of_business.match(/\b\d{6}\b/)?.[0];if(expected&&docs.address.postcode!==expected)issues.push('Address postcode differs from GST registry.');}
 if(docs.id){if(record?.constitution==='Proprietorship'&&docs.id.signatory&&!normalize(record.legal_name).includes(normalize(docs.id.signatory)))issues.push('Signatory differs from the proprietor in the registry.');if(!docs.id.signatory)issues.push('Signatory name is missing.');if(!docs.id.expiry||docs.id.expiry<TODAY)issues.push('Signatory ID is expired or unreadable.');}
 return{status:issues.length?'review':'verified_demo',issues,maskedGST:mask(gstin),gstStatus:record?.status??null,business:business??'Alternative registration',note:'Demo consistency checks only. These do not verify signatory authority or complete statutory telecom KYC.'};
}
export function transition(order,event){const flow=['submitted','site_check','scheduled','active'];if(event==='payment_failed')return{...order,status:'payment_failed'};if(event==='retry_payment'&&order.status==='payment_failed')return{...order,status:'submitted'};if(event==='delay'&&['site_check','scheduled'].includes(order.status))return{...order,delayed:true};if(event==='next'){const i=flow.indexOf(order.status);if(i<0||i===flow.length-1)throw new Error('Invalid transition');return{...order,status:flow[i+1],delayed:false};}throw new Error('Invalid transition');}
